      "nav.features": "功能",
      "nav.help": "使用指南",
      "nav.premium": "高级会员",
      "nav.coins": "欧泊与任务",
      "nav.community": "作品广场",
      "nav.news": "最新消息",
      "nav.faq": "常见问题",
